34	const PROCESSING_FEE = 5;
35	
36	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
37	
38	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	  staff: 80,
42	  potion: 40,
43	  rune: 25,
44	};
45	
46	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
47	
48	const BLOCK_SIZE = 3;
49	
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const groupBasePremium = (items: Item[]): number =>
53	  items.length === BLOCK_SIZE
54	    ? BLOCK_BASE_PREMIUM
55	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
56	
57	const groupByType = (items: Item[]): Item[][] => {
58	  const groups = new Map<string, Item[]>();
59	  for (const item of items) {
60	    const group = groups.get(item.type) ?? [];
61	    group.push(item);
62	    groups.set(item.type, group);
63	  }
64	  return [...groups.values()];
65	};
66	
67	const quotePremium = (step: QuoteStep): number => {
68	  const policyBasePremium = groupByType(step.items).reduce(
69	    (sum, group) => sum + groupBasePremium(group),
70	    0,
71	  );
72	  const firstInsuranceSurcharge =
73	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
74	  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
75	};
76	
77	export const runScenario = (scenario: Scenario): ScenarioResult => ({
78	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
79	});
